{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Oritavancin, a large glycosylated polycyclic antibiotic, showed only 5% CSF/plasma penetration in a rabbit meningitis model, directly demonstrating poor CNS access for a high-molecular-weight glycoside; this transfers to the query's similarly large, polar glycosidic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Mithramycin, a polycyclic glycoside with multiple sugar and hydroxyl groups, achieved a CSF:plasma ratio of only 0.12 in monkeys, indicating poor brain penetration; this is directly relevant to the query's anthracycline-like glycoside architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Erythromycin, a high-molecular-weight macrolide with multiple hydrogen-bond donors, achieved CSF concentrations far below serum in humans, supporting that large polar macrocyclic/glycosidic natural products do not achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Digitoxin, a cardiac glycoside, had a very low CSF/plasma ratio of 0.01-0.03 in dogs, reinforcing that glycoside conjugates with extensive polar surfaces are effectively excluded from the CNS.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, highly polar anthracycline-type glycoside with many hydrogen-bond donors/acceptors and a sugar moiety. Direct experimental evidence from closely transferable large glycosides (oritavancin, mithramycin, digitoxin, erythromycin) consistently shows poor CSF/brain penetration. The physicochemical prior of low passive BBB plausibility and high efflux liability agrees. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain or CSF measurement exists for the exact query molecule; the decision relies on transfer from structurally related large glycosides.",
    "Potential active uptake transport or disease-state BBB disruption was not experimentally assessed for the query.",
    "The exact ionization state and transporter substrate profile of the query are not experimentally defined."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

